/**
 * Turns the collected figures into the two generated files: the index the
 * engines and the in-app AI read, and the register people read. Pure: it takes
 * the figures and returns text, so the build script writes it and the check
 * compares against it with the same code.
 *
 * Nothing in either file depends on today's date, so the output only changes
 * when a catalogue does and `--check` can fail on drift.
 */

export const FIGURES_INDEX_VERSION = 'planeir-figures-index-1.0.0';

const KIND_TITLES = Object.freeze({
  law: 'Law in force',
  announced_law: 'Announced law',
  market: 'Market',
  planeir_assumption: 'Planeir assumption'
});

const CATALOGUE_TITLES = Object.freeze({
  ie_tax_rules: 'Irish tax rules',
  ie_planning_rules: 'Irish planning rules',
  ie_social_welfare: 'Social welfare rates',
  ie_fair_deal_rules: 'Fair Deal rules',
  house_purchase_rules: 'House Purchase rules',
  planeir_assumptions: 'Planeir central assumptions',
  ie_market: 'Market figures'
});

const GROUP_TITLES = Object.freeze({
  income_tax: 'Income tax',
  usc: 'Universal Social Charge',
  prsi: 'PRSI',
  lump_sum: 'Retirement lump sums',
  cgt: 'Capital gains tax',
  dirt: 'DIRT',
  sft: 'Standard Fund Threshold',
  exit_tax: 'Exit tax on investments',
  investment_account: 'Investment Account',
  pension_relief: 'Pension tax relief',
  arf: 'Approved retirement funds',
  state_pension_contributory: 'State Pension (Contributory) assumptions',
  social_welfare: 'Weekly rates',
  mortgage: 'Mortgage lending and illustration',
  stamp_duty: 'Stamp duty',
  help_to_buy: 'Help to Buy',
  first_home_scheme: 'First Home Scheme',
  deposit_savings: 'Deposit saving',
  purchase_costs: 'Purchase costs',
  income: 'Income',
  assets: 'Assets',
  home: 'The home',
  retained: 'What a person keeps',
  transfers: 'Transfers',
  review: 'Reviews',
  loan: 'Nursing Home Loan',
  assumption: 'Assumptions',
  market: 'Market'
});

/** The index as a module, with every figure and explainer frozen. */
export function renderIndexSource(figures, catalogues, explainers, explainersVersion) {
  return '/* Generated by scripts/build-figures-index.mjs. Do not edit. */\n'
    + `export const FIGURES_INDEX_VERSION = ${JSON.stringify(FIGURES_INDEX_VERSION)};\n\n`
    + `export const FIGURES_CATALOGUES = Object.freeze(${JSON.stringify(catalogues, null, 2)}.map(Object.freeze));\n\n`
    + `export const FIGURES_INDEX = Object.freeze(${JSON.stringify(figures, null, 2)}.map(Object.freeze));\n\n`
    + `export const EXPLAINERS_VERSION = ${JSON.stringify(explainersVersion)};\n\n`
    + `export const EXPLAINERS_INDEX = Object.freeze(${JSON.stringify(explainers, null, 2)}.map(Object.freeze));\n`;
}

/** The catalogues with their versions and how many figures each holds. */
export function summariseCatalogues(figures) {
  const byId = new Map();
  for (const figure of figures) {
    const entry = byId.get(figure.catalogue.id) ?? { id: figure.catalogue.id, version: figure.catalogue.version, count: 0 };
    entry.count += 1;
    byId.set(figure.catalogue.id, entry);
  }
  return [...byId.values()];
}

const escapeCell = (text) => String(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');

function sourceCell(figure) {
  const { title, url } = figure.source;
  return url ? `[${escapeCell(title)}](${url})` : escapeCell(title);
}

function checkedCell(figure) {
  const mark = figure.checkedOnFrom === 'catalogue' ? ' †' : (figure.checkedOnFrom === 'history' ? ' ‡' : '');
  return `${figure.checkedOn}${mark}`;
}

/** The topic a figure is listed under: the second part of its quantity, the third for House Purchase. */
function groupOf(figure) {
  const parts = figure.quantity.split('.');
  if (figure.catalogue.id === 'planeir_assumptions') return 'assumption';
  if (figure.catalogue.id === 'ie_market') return 'market';
  if (figure.catalogue.id === 'ie_fair_deal_rules') return parts[2];
  return figure.catalogue.id === 'house_purchase_rules' ? parts[2] : parts[1];
}

function table(rows) {
  return [
    '| Figure | Value | From | Status | Source | Checked | Used by | Id |',
    '|---|---|---|---|---|---|---|---|',
    ...rows.map((figure) => `| ${escapeCell(figure.label)}${figure.note ? `<br>*${escapeCell(figure.note)}*` : ''}${figure.explainers ? `<br>Explained: ${figure.explainers.map((id) => `\`${id}\``).join(', ')}` : ''} | ${escapeCell(figure.valueShown)} | ${figure.effectiveFrom ?? '—'} | ${figure.kind === 'announced_law' ? '**announced**' : figure.status.replace(/_/g, ' ')} | ${sourceCell(figure)} | ${checkedCell(figure)} | ${figure.usedBy.join(', ')} | \`${figure.id}\` |`)
  ].join('\n');
}

/** The register people read, grouped by catalogue and topic. */
export function renderRegisterMarkdown(figures, catalogues, explainers = [], explainersVersion = '') {
  const lines = [];
  lines.push('# Figures register');
  lines.push('');
  lines.push('<!-- Generated by scripts/build-figures-index.mjs from the catalogues. Do not edit by hand: run `npm run build:figures`. -->');
  lines.push('');
  lines.push('Every figure that can change: law, market prices and Planeir\'s own assumptions, each with its value, its source and when it was last checked. The in-app AI reads these through `getFigures`, and a weekly scheduled job keeps the market ones current. No figure is typed in anywhere else.');
  lines.push('');
  lines.push('| Kind | Meaning | Who changes it |');
  lines.push('|---|---|---|');
  lines.push('| Law in force | Set by legislation or a Revenue or Department rule that is in force | Edited when the law changes, with its source |');
  lines.push('| Announced law | Announced in a Budget or published as a Bill, not yet enacted | Edited when it is enacted or amended |');
  lines.push('| Market | A price or rate that moves on its own, worked out from the quotes it was read from | The weekly job adds quotes; code does the arithmetic |');
  lines.push('| Planeir assumption | A choice Planeir makes | A person only; a job never changes these |');
  lines.push('');
  lines.push('Counts: ' + Object.entries(KIND_TITLES).map(([kind, title]) => `${title} ${figures.filter((figure) => figure.kind === kind).length}`).join(', ') + `. Total ${figures.length}.`);
  lines.push('');
  lines.push('**Checked.** The day the value was read against its source. † means the figure has no check date of its own and shows the date its catalogue was last verified. ‡ means a Planeir choice with no review recorded, so the date shown is the day it was set.');
  lines.push('');
  lines.push('**From.** The day the value takes effect. A dash means the source states no date. A rule that a later tax year carries over unchanged is listed once, for the year it first took effect.');
  lines.push('');
  lines.push('Catalogues: ' + catalogues.map((catalogue) => `${CATALOGUE_TITLES[catalogue.id] ?? catalogue.id} \`${catalogue.version}\``).join('; ') + '.');
  lines.push('');

  for (const catalogue of catalogues) {
    const inCatalogue = figures.filter((figure) => figure.catalogue.id === catalogue.id);
    lines.push(`## ${CATALOGUE_TITLES[catalogue.id] ?? catalogue.id}`);
    lines.push('');
    lines.push(`Catalogue version \`${catalogue.version}\`. ${inCatalogue.length} figures.`);
    lines.push('');
    const groups = [...new Set(inCatalogue.map(groupOf))];
    for (const group of groups) {
      const rows = inCatalogue.filter((figure) => groupOf(figure) === group);
      if (groups.length > 1) {
        lines.push(`### ${GROUP_TITLES[group] ?? group.replace(/_/g, ' ')}`);
        lines.push('');
      }
      lines.push(table(rows));
      lines.push('');
    }
  }

  if (explainers.length > 0) {
    lines.push('## Explainers');
    lines.push('');
    lines.push(`Short, sourced, plain-language accounts of how the rules behind the figures work, for the story screen\u2019s hover and for the analyst to point to. Education only: an explainer says how a rule works, never what anyone should do, and it types no figure, because the screen fills those in from the register by id. Catalogue version \`${explainersVersion}\`. ${explainers.length} explainers. The in-app AI reads them through \`getExplainers\`. A figure lists the explainers that cover it under its label above.`);
    lines.push('');
    for (const explainer of explainers) {
      lines.push(`### ${explainer.title}`);
      lines.push('');
      lines.push(`\`${explainer.id}\``);
      lines.push('');
      lines.push(explainer.text);
      lines.push('');
      const rules = explainer.ruleIds.map((id) => `\`${id}\``);
      const ids = explainer.figureIds.map((id) => `\`${id}\``);
      lines.push(`Explains: ${[...ids, ...rules.map((rule) => `${rule} (every figure beneath it)`)].join(', ')}. Covers ${explainer.coversFigureIds.length} figures.`);
      lines.push('');
      lines.push(`Sources, read ${explainer.checkedOn}: ${explainer.sources.map((source) => `[${escapeCell(source.title)}](${source.url})`).join('; ')}.`);
      lines.push('');
    }
  }

  const market = figures.filter((figure) => figure.kind === 'market');
  if (market.length > 0) {
    lines.push('## Market figures: how each value is worked out');
    lines.push('');
    lines.push('Internal provenance. The provider names below are for the audit trail and are never shown to clients: a label, a basis or a source title never names one.');
    lines.push('');
    for (const figure of market) {
      lines.push(`### ${figure.label}`);
      lines.push('');
      const method = figure.method;
      const how = method.kind === 'reviewed'
        ? `Held as a standard planning assumption, ${figure.valueShown}, as of ${method.reviewedOn}; not worked out from the quotes. The quotes below are the evidence for it.`
        : `${method.kind === 'single' ? 'Single source' : method.kind[0].toUpperCase() + method.kind.slice(1)} of the quotes below${method.roundTo ? `, rounded to the nearest ${method.roundTo}` : ''}.`;
      lines.push(`\`${figure.id}\` is **${figure.valueShown}**. ${how} Checked ${figure.checkedOn}, last changed ${figure.changedOn}, reviewed every ${figure.reviewEveryDays} days. Figure version \`${figure.figureVersion}\`.`);
      if (figure.evidence) {
        lines.push('');
        lines.push(`Evidence median ${(figure.evidence.median * 100).toFixed(2)}%, ${(Math.abs(figure.evidence.gap) * 100).toFixed(2)} points ${figure.evidence.gap >= 0 ? 'above' : 'below'} the chosen value${figure.evidence.drifted ? ' (past the drift limit, so the check warns)' : ''}.`);
      }
      lines.push('');
      lines.push('| Quote | Value | Quoted as | Effective | Read on |');
      lines.push('|---|---|---|---|---|');
      for (const observation of figure.observations) {
        lines.push(`| [${escapeCell(observation.sourceLabel)}](${observation.url}) | ${(observation.value * 100).toFixed(2)}% | ${escapeCell(observation.quotedAs)} | ${observation.effective ?? '—'} | ${observation.retrievedOn} |`);
      }
      lines.push('');
    }
  }
  return lines.join('\n').replace(/\n+$/, '\n');
}
